method correct_bracketing(brackets: string) returns (result: bool)
    requires brackets != null
    requires forall i :: 0 <= i < brackets.Length ==> (brackets[i] == '<' || brackets[i] == '>')
    ensures result == (CountOpenBrackets(brackets) == CountCloseBrackets(brackets))

    // Helper function to count opening brackets
    function CountOpenBrackets(s: string): int
        reads s
        ensures CountOpenBrackets(s) >= 0
    {
        var count := 0;
        var i := 0;
        while i < s.Length
            invariant 0 <= count <= i
            invariant i <= s.Length
        {
            if s[i] == '<' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }

    // Helper function to count closing brackets
    function CountCloseBrackets(s: string): int
        reads s
        ensures CountCloseBrackets(s) >= 0
    {
        var count := 0;
        var i := 0;
        while i < s.Length
            invariant 0 <= count <= i
            invariant i <= s.Length
        {
            if s[i] == '>' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }
```

